// Oracle for RandomGenerator.nextExponential() and nextGaussian(mean, stddev)
// (JDK 25) in the Rucene port of randomizedtesting 2.8.1.
//
// 1. Dumps the numeric tables of jdk.internal.util.random.RandomSupport
//    .DoubleZigguratTables (JDK 25, OpenJDK, GPLv2 with Classpath Exception)
//    as Rust constants to ziggurat_tables.rs, which regenerate.sh copies to
//    src/jdk/data/ and the crate embeds with include!. The values are read
//    from the running JVM by reflection (requires
//    --add-opens java.base/jdk.internal.util.random=ALL-UNNAMED); no JDK
//    source is copied.
// 2. Writes ziggurat_draws.tsv: 3 generators x 20 seeds x 10 000 draws of
//    nextExponential(), nextGaussian() and nextGaussian(mean, stddev) on a
//    parameter grid, and ziggurat_errors.tsv: the argument errors.
package com.carrotsearch.randomizedtesting;

import java.io.PrintWriter;
import java.lang.reflect.Field;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.Random;

import static com.carrotsearch.randomizedtesting.OracleSupport.*;

public class ZigguratOracle {
  static final String TABLES = "jdk.internal.util.random.RandomSupport$DoubleZigguratTables";

  static Field field(Class<?> c, String name) throws Exception {
    Field f = c.getDeclaredField(name);
    f.setAccessible(true);
    return f;
  }

  static String d(double v) {
    return "f64::from_bits(0x" + String.format("%016x", Double.doubleToRawLongBits(v)) + ")";
  }

  static void tables(Path out) throws Exception {
    Class<?> c = Class.forName(TABLES);
    try (PrintWriter w = new PrintWriter(Files.newBufferedWriter(out.resolve("ziggurat_tables.rs")))) {
      w.println("// Generated by tests/fixtures/oracle (ZigguratOracle.java, regenerate.sh): the");
      w.println("// values of " + TABLES.replace('$', '.'));
      w.println("// read by reflection from the running OpenJDK " + System.getProperty("java.version")
          + " JVM. OpenJDK is licensed under GPLv2 with the Classpath Exception;");
      w.println("// see the crate's NOTICE. Do not edit.");
      for (String prefix : new String[] {"exponential", "normal"}) {
        String up = prefix.toUpperCase();
        for (String s : new String[] {"NumberOfLayers", "LayerMask", "AliasMask", "SignCorrectionMask", "InflectionIndex"}) {
          Field f;
          try { f = field(c, prefix + s); } catch (NoSuchFieldException e) { continue; }
          w.println("pub(super) const " + up + "_" + snake(s) + ": i32 = " + f.getInt(null) + ";");
        }
        w.println("pub(super) const " + up + "_X0: f64 = " + d(field(c, prefix + "X0").getDouble(null)) + ";");
        for (String s : new String[] {"ConvexMargin", "ConcaveMargin"}) {
          Field f;
          try { f = field(c, prefix + s); } catch (NoSuchFieldException e) { continue; }
          w.println("pub(super) const " + up + "_" + snake(s) + ": i64 = " + f.getLong(null) + ";");
        }
        for (String s : new String[] {"X", "Y"}) {
          double[] a = (double[]) field(c, prefix + s).get(null);
          w.println("pub(super) const " + up + "_" + s + ": [f64; " + a.length + "] = [");
          for (double v : a) w.println("    " + d(v) + ",");
          w.println("];");
        }
        long[] t = (long[]) field(c, prefix + "AliasThreshold").get(null);
        w.println("pub(super) const " + up + "_ALIAS_THRESHOLD: [i64; " + t.length + "] = [");
        for (long v : t) w.println("    " + v + ",");
        w.println("];");
        byte[] m = (byte[]) field(c, prefix + "AliasMap").get(null);
        w.println("pub(super) const " + up + "_ALIAS_MAP: [i8; " + m.length + "] = [");
        for (byte v : m) w.println("    " + v + ",");
        w.println("];");
      }
    }
  }

  static String snake(String camel) {
    return camel.replaceAll("([a-z])([A-Z])", "$1_$2").toUpperCase();
  }

  static final double INF = Double.POSITIVE_INFINITY;
  static final double NAN = Double.NaN;

  /** (mean, stddev) pairs of the draw grid; every stddev here is accepted. */
  static double[][] gaussianParams() {
    return new double[][] {
      {0, 1}, {5, 2}, {-3, 0.5}, {0, 0}, {7, 0}, {1, -0.0}, {1e300, 1e10}, {0, Double.MAX_VALUE},
      {0, Double.MIN_VALUE}, {0, INF}, {INF, 1}, {-INF, 1}, {INF, 0}, {-INF, INF}, {NAN, 1}, {0, NAN}, {NAN, NAN},
    };
  }

  static String hex(double v) { return Long.toHexString(Double.doubleToLongBits(v)); }

  static void draws(Path out) throws Exception {
    try (PrintWriter w = new PrintWriter(Files.newBufferedWriter(out.resolve("ziggurat_draws.tsv")))) {
      w.println("# gen\tseed\tmethod\tfnv64\tfirst values");
      for (String kind : new String[] {"jdk", "xoro", "asserting"}) {
        for (long seed : seeds()) {
          String k = kind + "\t" + Long.toHexString(seed) + "\t";
          Random r = RandomizedTestingOracle.gen(kind, seed);
          Rec rec = new Rec();
          for (int i = 0; i < RandomizedTestingOracle.DRAWS; i++) rec.d(r.nextExponential());
          w.println(k + "nextExponential()\t" + rec.line());
          r = RandomizedTestingOracle.gen(kind, seed);
          rec = new Rec();
          for (int i = 0; i < RandomizedTestingOracle.DRAWS; i++) rec.d(r.nextGaussian());
          w.println(k + "nextGaussian()\t" + rec.line());
          for (double[] p : gaussianParams()) {
            r = RandomizedTestingOracle.gen(kind, seed);
            rec = new Rec();
            for (int i = 0; i < RandomizedTestingOracle.DRAWS; i++) rec.d(r.nextGaussian(p[0], p[1]));
            w.println(k + "nextGaussian(" + hex(p[0]) + "," + hex(p[1]) + ")\t" + rec.line());
          }
          // Interleaved: the ziggurat draws mixed with the polar nextGaussian()
          // and its cached second value.
          r = RandomizedTestingOracle.gen(kind, seed);
          rec = new Rec();
          for (int i = 0; i < RandomizedTestingOracle.DRAWS; i++) {
            rec.d(r.nextGaussian()); rec.d(r.nextExponential()); rec.d(r.nextGaussian(2, 3));
            rec.l(r.nextLong()); rec.d(r.nextGaussian());
          }
          w.println(k + "interleaved\t" + rec.line());
        }
      }
    }
  }

  static void errors(Path out) throws Exception {
    try (PrintWriter w = new PrintWriter(Files.newBufferedWriter(out.resolve("ziggurat_errors.tsv")))) {
      w.println("# gen\tcall\tclass\tmessage");
      for (String kind : new String[] {"jdk", "xoro", "asserting"}) {
        Random r = RandomizedTestingOracle.gen(kind, 7);
        String k = kind + "\t";
        tryRecord(w, k + "nextGaussian(0,-1)", () -> r.nextGaussian(0, -1));
        tryRecord(w, k + "nextGaussian(0,-inf)", () -> r.nextGaussian(0, -INF));
        tryRecord(w, k + "nextGaussian(0,-min)", () -> r.nextGaussian(0, -Double.MIN_VALUE));
        tryRecord(w, k + "nextGaussian(NaN,-1)", () -> r.nextGaussian(NAN, -1));
        tryRecord(w, k + "nextGaussian(0,-0)", () -> r.nextGaussian(0, -0.0));
        tryRecord(w, k + "nextGaussian(0,NaN)", () -> r.nextGaussian(0, NAN));
        // An argument error draws nothing: the next value equals a fresh generator's first.
        Random a = RandomizedTestingOracle.gen(kind, 11);
        try { a.nextGaussian(0, -1); } catch (IllegalArgumentException e) { /* expected */ }
        Random b = RandomizedTestingOracle.gen(kind, 11);
        w.println(k + "noDrawOnError\t" + (a.nextLong() == b.nextLong()) + "\t-");
      }
    }
  }

  public static void main(String[] args) throws Exception {
    Path out = Paths.get(args[0]);
    Files.createDirectories(out);
    tables(out);
    draws(out);
    errors(out);
  }
}
